#[actor(
    TelegramCreateForumTopicActor,
    inports::<100>(chat_id, name, icon_color, icon_custom_emoji_id),
    outports::<50>(response, error),
    state(MemoryState)
)]
pub async fn telegram_create_forum_topic(context: ActorContext) -> Result<HashMap<String, Message>, Error> {
    let inputs = context.get_payload();
    let actor_config = context.get_config();

    let mut endpoint = "/createForumTopic".to_string();

    let url = format!("{}{}", BASE_URL.trim_end_matches('/'), endpoint);

    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .build()?;

    let mut builder = client.post(&url);
    builder = builder.header("Content-Type", "application/json");
    builder = apply_auth(actor_config, builder)?;

    let mut body = serde_json::Map::new();
    if let Some(val) = inputs.get("chat_id") {
        body.insert("chat_id".to_string(), val.clone().into());
    }
    if let Some(val) = inputs.get("name") {
        body.insert("name".to_string(), val.clone().into());
    }
    if let Some(val) = inputs.get("icon_color") {
        body.insert("icon_color".to_string(), val.clone().into());
    }
    if let Some(val) = inputs.get("icon_custom_emoji_id") {
        body.insert("icon_custom_emoji_id".to_string(), val.clone().into());
    }
    if !body.is_empty() {
        builder = builder.json(&serde_json::Value::Object(body));
    }

    let mut output = HashMap::new();
    match builder.send().await {
        Ok(resp) => {
            let status = resp.status().as_u16();
            let headers: HashMap<String, String> = resp.headers()
                .iter()
                .filter_map(|(k, v)| v.to_str().ok().map(|val| (k.to_string(), val.to_string())))
                .collect();
            let body_text = resp.text().await.unwrap_or_default();
            let body_value: Value = serde_json::from_str(&body_text).unwrap_or(Value::String(body_text));
            output.insert("response".to_string(), Message::object(EncodableValue::from(json!({
                "status": status,
                "headers": headers,
                "body": body_value,
            }))));
        }
        Err(e) => {
            output.insert("error".to_string(), Message::Error(format!("POST /createForumTopic failed: {}", e).into()));
        }
    }

    Ok(output)
}

